export type IconName = keyof typeof ICONS;

export interface IconProps extends SVGProps<SVGSVGElement> {
  name: IconName;
}

export function Icon({ name, className, ...props }: IconProps) {
  const icon = ICONS[name];
  // Data-driven callers cast plain strings to IconName; a name missing from the
  // registry must render nothing rather than crash SSR/prerender.
  if (!icon) {
    if (import.meta.env.DEV) console.warn(`[Icon] no registry entry for "${name}"`);
    return null;
  }
  return (
    <svg
      viewBox={icon.viewBox}
      fill="currentColor"
      aria-hidden="true"
      focusable="false"
      className={className ? `inline-block h-[1em] w-[1em] shrink-0 ${className}` : "inline-block h-[1em] w-[1em] shrink-0"}
      {...props}>
      <path d={icon.d} />
    </svg>
  );
}
